command:
$ErrorActionPreference = 'Stop'
$baseSha = '45e75c60db5c3e8ce1b96e8357a26ef4d824369c'
$branch = 'issue-416-gemini-knowledge-consolidation-eval'
$failed = $false
function Invoke-Checked([string]$Label, [scriptblock]$Action) {
  Write-Host "=== $Label ==="
  & $Action
  if ($LASTEXITCODE -ne 0) { throw "$Label failed with exit $LASTEXITCODE" }
}
try {
  git fetch --no-tags origin $branch main
  if ($LASTEXITCODE -ne 0) { throw 'Unable to fetch PR branch/main' }
  if ((git rev-parse "origin/$branch").Trim() -ne $baseSha) { throw 'PR branch head moved before DCOIR cleanup retry' }
  git checkout -B $branch $baseSha
  if ($LASTEXITCODE -ne 0) { throw 'Unable to checkout PR branch head' }
  @'
from pathlib import Path

path = Path('project_sources/agent_runtime/tools/evaluate_gemini_knowledge_consolidation.py')
text = path.read_text(encoding='utf-8')
old = "SAFE_GROUP_ID_RE = re.compile(r'^[a-z0-9][a-z0-9_]*$')"
new = "SAFE_GROUP_ID_PATTERN = r'^[a-z0-9][a-z0-9_]*$'"
if text.count(old) != 1:
    raise SystemExit(f'expected one compiled group regex, found {text.count(old)}')
text = text.replace(old, new, 1)
old_use = 'not SAFE_GROUP_ID_RE.fullmatch(group_id)'
new_use = 're.fullmatch(SAFE_GROUP_ID_PATTERN, group_id) is None'
if text.count(old_use) != 2:
    raise SystemExit(f'expected two group-regex uses, found {text.count(old_use)}')
text = text.replace(old_use, new_use)
path.write_text(text, encoding='utf-8')
'@ | python -
  if ($LASTEXITCODE -ne 0) { throw 'DCOIR false-positive cleanup edit failed' }
  git diff --check
  if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed' }
  git add project_sources/agent_runtime/tools/evaluate_gemini_knowledge_consolidation.py
  git diff --cached --quiet
  if ($LASTEXITCODE -eq 0) { throw 'Cleanup produced no staged changes' }
  git -c user.name='Malware Devil' -c user.email='34285973+malwaredevil@users.noreply.github.com' commit -m 'Avoid DCOIR regex false positive'
  if ($LASTEXITCODE -ne 0) { throw 'Cleanup commit failed' }
  $testedSha = (git rev-parse HEAD).Trim()
  Write-Host "tested_branch_head=$testedSha"
  Invoke-Checked 'Compile evaluator and tests' { python -m py_compile project_sources/agent_runtime/tools/evaluate_gemini_knowledge_consolidation.py project_sources/agent_runtime/tests/evaluate_gemini_knowledge_consolidation_selftest.py project_sources/agent_runtime/tests/project_agent_knowledge_selftest.py }
  Invoke-Checked 'Standalone Gemini consolidation evaluator self-tests' { python project_sources/agent_runtime/tests/evaluate_gemini_knowledge_consolidation_selftest.py }
  Invoke-Checked 'Integrated governed Knowledge self-tests' { python project_sources/agent_runtime/tests/project_agent_knowledge_selftest.py }
  Invoke-Checked '1 Shared source contract' { python project_sources/agent_runtime/tools/validate_shared_agent_source_contract.py }
  Invoke-Checked '2 Shared source contract self-tests' { python project_sources/agent_runtime/tests/validate_shared_agent_source_contract_selftest.py }
  Invoke-Checked '3 Behavior adapter materialization check' { python project_sources/agent_runtime/tools/materialize_agent_behavior_adapters.py --check }
  Invoke-Checked '4 Behavior adapter self-tests' { python project_sources/agent_runtime/tests/materialize_agent_behavior_adapters_selftest.py }
  Invoke-Checked '5 Knowledge projection check' { python project_sources/agent_runtime/tools/project_agent_knowledge.py --check }
  Invoke-Checked '6 Knowledge projection plus consolidation self-tests' { python project_sources/agent_runtime/tests/project_agent_knowledge_selftest.py }
  Invoke-Checked '7 OpenAI DCOIR package check' { python project_sources/agent_runtime/tools/build_openai_dcoir_analyst.py --check }
  Invoke-Checked '8 OpenAI DCOIR package self-tests' { python project_sources/agent_runtime/tests/build_openai_dcoir_analyst_selftest.py }
  Invoke-Checked '9 OpenAI USB package check' { python project_sources/agent_runtime/tools/build_openai_usb_reporting.py --check }
  Invoke-Checked '10 OpenAI USB package self-tests plus unified parity' { python project_sources/agent_runtime/tests/build_openai_usb_reporting_selftest.py }
  $tracked = git status --porcelain --untracked-files=no
  if ($LASTEXITCODE -ne 0) { throw 'Unable to inspect tracked repository state' }
  if ($tracked) { $tracked | Out-Host; throw 'Validation changed tracked repository files' }
  git push origin HEAD:$branch
  if ($LASTEXITCODE -ne 0) { throw 'Push failed' }
  Write-Host "validated_and_pushed_head=$testedSha"
}
catch {
  $failed = $true
  Write-Host "VALIDATION_FAILURE=$($_.Exception.Message)"
}
finally {
  git rebase --abort 2>$null
  git reset --hard 2>$null
  git fetch --no-tags origin main
  git checkout -B main origin/main
  Write-Host "runner_restored_to=$(git rev-parse --abbrev-ref HEAD)"
}
if ($failed) { exit 1 }
